  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'minShadowLight'), minShadowLight);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'baseTex'), 0);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'waterTex'), 1);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'wallTex'), 2);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightTex'), 3);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'noiseTex'), 4);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'surfaceTextureMap'), 5);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'customSurfaceAtlas'), 15);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'curlTex'), 6);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'dropletSizeTex'), 6);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightningTex'), 7);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightningDataTex'), 8);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'ambientLightTex'), 9);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightningOnLightTex'), 11);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightningCloudFlashTex'), 12);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'lightningSurfFlashTex'), 13);
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'sunColumnTex'), 14);
  // Unit 10 is free in realistic display (0–15 only; unit 16 is invalid on most GPUs).
  gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'smokeTex'), 10);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'dryLapse'), dryLapse);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'cellHeight'), cellHeight);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'visualQuality'), 1.0);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'smoothClouds'), guiControls.smoothClouds !== false ? 1.0 : 0.0);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'floodVizStrength'),
    guiControls.floodWaterOpacity != null ? guiControls.floodWaterOpacity
      : (guiControls.floodVizStrength != null ? guiControls.floodVizStrength : 0.75));
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'fogHazeStrength'), guiControls.fogHazeStrength != null ? guiControls.fogHazeStrength : 0.0);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueStartThreshold'), guiControls.greenHueStartThreshold != null ? guiControls.greenHueStartThreshold : 0.8);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueEndThreshold'), guiControls.greenHueEndThreshold != null ? guiControls.greenHueEndThreshold : 1.8);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueStrength'), guiControls.greenHueStrength != null ? guiControls.greenHueStrength : 0.45);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueBrightness'), guiControls.greenHueBrightness != null ? guiControls.greenHueBrightness : 1.0);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueSaturation'), guiControls.greenHueSaturation != null ? guiControls.greenHueSaturation : 1.0);
  gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueHue'), guiControls.greenHueHue != null ? guiControls.greenHueHue : 0.0);
  uploadCloudsRainUniforms();

  if (lightningIllumProgram) {
    gl.useProgram(lightningIllumProgram);
    gl.uniform1i(gl.getUniformLocation(lightningIllumProgram, 'waterTex'), 0);
    gl.uniform1i(gl.getUniformLocation(lightningIllumProgram, 'lightningTex'), 1);
    gl.uniform2f(gl.getUniformLocation(lightningIllumProgram, 'resolution'), sim_res_x, sim_res_y);
    gl.uniform2f(gl.getUniformLocation(lightningIllumProgram, 'texelSize'), texelSizeX, texelSizeY);
    gl.uniform2f(gl.getUniformLocation(lightningIllumProgram, 'aspectRatios'), sim_aspect, canvas.width / Math.max(canvas.height, 1));
  }

  gl.useProgram(lightningLocationProgram);
  gl.uniform1i(gl.getUniformLocation(lightningLocationProgram, 'precipFeedbackTex'), 0);
  gl.uniform2f(gl.getUniformLocation(lightningLocationProgram, 'resolution'), sim_res_x, sim_res_y);
  gl.uniform2f(gl.getUniformLocation(lightningLocationProgram, 'texelSize'), texelSizeX, texelSizeY);

  gl.useProgram(precipitationProgram);
  gl.uniform1i(gl.getUniformLocation(precipitationProgram, 'baseTex'), 0);
  gl.uniform1i(gl.getUniformLocation(precipitationProgram, 'waterTex'), 1);
  gl.uniform1i(gl.getUniformLocation(precipitationProgram, 'lightningDataTex'), 2);
  gl.uniform2f(gl.getUniformLocation(precipitationProgram, 'resolution'), sim_res_x, sim_res_y);
  gl.uniform2f(gl.getUniformLocation(precipitationProgram, 'texelSize'), texelSizeX, texelSizeY);
  gl.uniform1f(gl.getUniformLocation(precipitationProgram, 'dryLapse'), dryLapse);
  {
    const locType = gl.getUniformLocation(precipitationProgram, 'userInputType');
    const locVals = gl.getUniformLocation(precipitationProgram, 'userInputValues');
    const locWrap = gl.getUniformLocation(precipitationProgram, 'wrapHorizontally');
    if (locType) gl.uniform1i(locType, -1);
    if (locVals) gl.uniform4f(locVals, -2.0, -2.0, 0.0, 0.0);
    if (locWrap) gl.uniform1i(locWrap, guiControls.wrapHorizontally ? 1 : 0);
  }
  gl.useProgram(IRtempDisplayProgram);
  gl.uniform2f(gl.getUniformLocation(IRtempDisplayProgram, 'resolution'), sim_res_x, sim_res_y);
  gl.uniform2f(gl.getUniformLocation(IRtempDisplayProgram, 'texelSize'), texelSizeX, texelSizeY);
  gl.uniform1i(gl.getUniformLocation(IRtempDisplayProgram, 'lightTex'), 0);
  gl.uniform1i(gl.getUniformLocation(IRtempDisplayProgram, 'wallTex'), 2);
  gl.uniform1i(gl.getUniformLocation(IRtempDisplayProgram, 'colorScalesTex'), 9);

  gl.useProgram(postProcessingProgram);
  gl.uniform1i(gl.getUniformLocation(postProcessingProgram, 'hdrTex'), 0);
  gl.uniform1i(gl.getUniformLocation(postProcessingProgram, 'bloomTex'), 1);


  gl.useProgram(isolateBrightPartsProgram);
  gl.uniform1i(gl.getUniformLocation(isolateBrightPartsProgram, 'hdrTex'), 0);

  // console.time('Set uniforms');
  setGuiUniforms(); // all uniforms changed by gui
  // console.timeEnd('Set uniforms')

  buildColorScaleEditor();
  buildKeybindEditor();
  // Sky controls live in Shader Menu (Sky tab). Legacy buildSkyEditor kept in source for reference.
  if (window.ShaderMenu && window.ShaderMenu.menu) {
    function uploadAppearanceUniforms()
    {
      if (!postProcessingProgram)
        return;
      gl.useProgram(postProcessingProgram);
      if (postProc_exposure_loc !== null) {
        gl.uniform1f(postProc_exposure_loc, guiControls.exposure);
        gl.uniform1f(postProc_saturation_loc, guiControls.saturation);
        gl.uniform1f(postProc_contrast_loc, guiControls.contrast);
        if (postProc_bloomStrength_loc !== null)
          gl.uniform1f(postProc_bloomStrength_loc, guiControls.bloomStrength ?? 1.0);
      }
      if (realisticDisplayProgram) {
        gl.useProgram(realisticDisplayProgram);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'floodVizStrength'), guiControls.floodWaterOpacity);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'fogHazeStrength'), guiControls.fogHazeStrength);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'smoothClouds'), guiControls.smoothClouds !== false ? 1.0 : 0.0);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'minShadowLight'), guiControls.minShadowLight);
        gl.uniform1i(gl.getUniformLocation(realisticDisplayProgram, 'enableRainbows'), guiControls.enableRainbows !== false ? 1 : 0);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueStartThreshold'), guiControls.greenHueStartThreshold != null ? guiControls.greenHueStartThreshold : 0.8);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueEndThreshold'), guiControls.greenHueEndThreshold != null ? guiControls.greenHueEndThreshold : 1.8);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueStrength'), guiControls.greenHueStrength != null ? guiControls.greenHueStrength : 0.45);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueBrightness'), guiControls.greenHueBrightness != null ? guiControls.greenHueBrightness : 1.0);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueSaturation'), guiControls.greenHueSaturation != null ? guiControls.greenHueSaturation : 1.0);
        gl.uniform1f(gl.getUniformLocation(realisticDisplayProgram, 'greenHueHue'), guiControls.greenHueHue != null ? guiControls.greenHueHue : 0.0);
      }
      if (skyBackgroundDisplayProgram) {
        gl.useProgram(skyBackgroundDisplayProgram);
        gl.uniform1f(gl.getUniformLocation(skyBackgroundDisplayProgram, 'minShadowLight'), guiControls.minShadowLight);
      }
    }

    function applyAppearanceFromPack(appearance)
    {
      if (!appearance) return;
      const keys = [ 'exposure', 'saturation', 'contrast', 'bloomStrength', 'enableRainbows',
        'smoothClouds', 'floodWaterOpacity', 'fogHazeStrength', 'minShadowLight' ];
      for (let i = 0; i < keys.length; i++) {
        const k = keys[i];
        if (appearance[k] !== undefined)
          guiControls[k] = appearance[k];
      }
      if (guiControls.floodWaterOpacity != null)
        guiControls.floodVizStrength = guiControls.floodWaterOpacity;
      uploadAppearanceUniforms();
    }

    if (window.ShaderMenu.runtime) {
      window.ShaderMenu.runtime.init({
        gl : gl,
        getStockSource : async function(stage) {
          const map = {
            post : 'postProcessingShader.frag',
            sky : 'skyBackgroundDisplayShader.frag',
            realistic : 'realisticDisplayShader.frag',
          };
          const name = map[stage];
          if (!name) return '';
          const url = 'shaders/fragment/' + name + '?v=' + SHADER_ASSET_VERSION;
          const res = await fetch(url);
          return await res.text();
        },
        recompileStage : async function(stage, sourceString) {
          // Validate compile only; edited sources persist in localStorage.
          // Reload the page to use custom GLSL in the live pipeline.
          try {
            let src = sourceString;
            if (src.includes('#include "common.glsl"') && typeof commonSource === 'string')
              src = src.replace('#include "common.glsl"', commonSource);
            if (src.includes('#include "commonDisplay.glsl"') && typeof commonDisplaySource === 'string')
              src = src.replace('#include "commonDisplay.glsl"', commonDisplaySource);
            if (src.includes('#include "cloudVisual.glsl"') && typeof cloudVisualSource === 'string')
              src = src.replace('#include "cloudVisual.glsl"', cloudVisualSource);
            if (src.includes('#include "lightningV2.glsl"') && typeof lightningV2Source === 'string')
              src = src.replace('#include "lightningV2.glsl"', lightningV2Source);
            const shader = gl.createShader(gl.FRAGMENT_SHADER);
            gl.shaderSource(shader, src);
            gl.compileShader(shader);
            if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
              const infoLog = gl.getShaderInfoLog(shader);
              gl.deleteShader(shader);
              return { ok : false, error : infoLog || 'Compile failed' };
            }
            gl.deleteShader(shader);
            return { ok : true, message : 'Compiled OK. Reload the page to apply.' };
          } catch (e) {
            return { ok : false, error : (e && e.message) ? e.message : String(e) };
          }
        },
      });
    }

    window.ShaderMenu.menu.buildShaderMenu({
      getGuiControls : () => guiControls,
      getSkySettings : () => skySettings,
      setSkySettings : (obj) => {
        // Keep existing sky fields when applying a partial update.
        skySettings = Object.assign(cloneSkySettings(SKY_SETTINGS_DEFAULTS), skySettings, obj || {});
      },
      getSkyDefaults : () => cloneSkySettings(SKY_SETTINGS_DEFAULTS),
      saveSkySettings : saveSkySettings,
      uploadSkyUniforms : uploadSkyUniforms,
      resetSkySettings : resetSkySettingsToDefaults,
      getCloudsRain : () => cloudsRainSettings,
      setCloudsRain : (obj) => {
        // Merge into the CURRENT settings so single-field UI edits keep prior values.
        // Pack apply still works: packs pass a full cloudsRain object that overwrites all keys.
        const patched = Object.assign({}, cloudsRainSettings, obj || {});
        if (window.ShaderMenu && window.ShaderMenu.packs)
          cloudsRainSettings = window.ShaderMenu.packs.mergeCloudsRain(patched);
        else
          cloudsRainSettings = patched;
        saveCloudsRainSettings();
        uploadCloudsRainUniforms();
      },
      resetCloudsRain : resetCloudsRainSettings,
      uploadCloudsRainUniforms : uploadCloudsRainUniforms,
      uploadAppearanceUniforms : uploadAppearanceUniforms,
      applyAppearanceFromPack : applyAppearanceFromPack,
      onSkyTimeChange : {
        onUpdateTimeOfDaySlider : function() {
          if (typeof onUpdateTimeOfDaySlider === 'function') onUpdateTimeOfDaySlider();
        },
        updateSunlight : function() {
          if (typeof updateSunlight === 'function') updateSunlight();
        },
        uploadClimateUniforms : function() {
          if (typeof uploadClimateUniforms === 'function') uploadClimateUniforms();
        },
        enableRealtimeMode : function() {
          if (typeof enableRealtimeMode === 'function') enableRealtimeMode();
        },
        resetRealtimeClockState : function() {
          if (typeof resetRealtimeClockState === 'function') resetRealtimeClockState();
        },
      },
      skyVec3ToHex : skyVec3ToHex,
      skyHexToVec3 : skyHexToVec3,
      getGl : () => gl,
      getStockShaderSource : async function(stage) {
        const map = {
          post : 'postProcessingShader.frag',
          sky : 'skyBackgroundDisplayShader.frag',
          realistic : 'realisticDisplayShader.frag',
        };
        const name = map[stage];
        if (!name) return '';
        const res = await fetch('shaders/fragment/' + name + '?v=' + SHADER_ASSET_VERSION);
        return await res.text();
      },
      recompileStage : async function(stage, source) {
        if (window.ShaderMenu && window.ShaderMenu.runtime) {
          window.ShaderMenu.runtime.setEditedSource(stage, source);
          return window.ShaderMenu.runtime.applyStage(stage);
        }
        return { ok : false, error : 'Runtime not ready' };
      },
    });
  }
  if (typeof buildUserInteractionMenu === 'function')
    buildUserInteractionMenu();
  else if (window.UserInteraction && window.UserInteraction.menu)
    window.UserInteraction.menu.buildUserInteractionMenu();
  if (typeof ControlHelp !== 'undefined')
    ControlHelp.attachCustomPanels();

  gl.bindVertexArray(fluidVao);

  // if no save file was loaded
  // Use setup shader to set initial conditions
  if (initialWallTex == null) {
    gl.viewport(0, 0, sim_res_x, sim_res_y);
    gl.useProgram(setupProgram);
    // Render to both framebuffers
    gl.bindFramebuffer(gl.FRAMEBUFFER, frameBuff_0);
    gl.drawBuffers([ gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1, gl.COLOR_ATTACHMENT2, gl.COLOR_ATTACHMENT3 ]);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

    gl.bindFramebuffer(gl.FRAMEBUFFER, frameBuff_1);
    gl.drawBuffers([ gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1, gl.COLOR_ATTACHMENT2, gl.COLOR_ATTACHMENT3 ]);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }


  if (!SETUP_MODE) {
    startSimulation();
  }

  if (guiControls.sound) {
    soundSystem = new SoundSystem();
  }

  await loadingBar.set(95, 'Loading sounds'); // loading complete
  if (typeof stopMenuBackgroundSlideshow === 'function') {
    stopMenuBackgroundSlideshow();
  }

  var srcVAO;
  var destVAO;
  var destTF;
  srcVAO = precipitationVao_0;
  destVAO = precipitationVao_1;
  destTF = precipitationTF_1;

  // preload uniform locations - avoids expensive driver roundtrips every frame
  var uniformLocation_boundaryProgram_iterNum = gl.getUniformLocation(boundaryProgram, 'iterNum');
  var uniformLocation_boundaryProgram_vorticity = gl.getUniformLocation(boundaryProgram, 'vorticity');
  var uniformLocation_boundaryProgram_lightEffectScale = gl.getUniformLocation(boundaryProgram, 'lightEffectScale');
  var ulocsReady = false; // flag so updateSunlight skips GPU calls before cache is built

  // updateSunlight uniforms
  const uloc_boundary_sunAngle         = gl.getUniformLocation(boundaryProgram,            'sunAngle');
  const uloc_boundary_sunAzimuth       = gl.getUniformLocation(boundaryProgram,            'sunAzimuth');
  const uloc_boundary_sunColumnTex     = gl.getUniformLocation(boundaryProgram,            'sunColumnTex');
  const uloc_boundary_latitudeBasedTemperature = gl.getUniformLocation(boundaryProgram,   'latitudeBasedTemperature');
  const uloc_lighting_sunIntensity     = gl.getUniformLocation(lightingProgram,             'sunIntensity');
  const uloc_lighting_sunAngle         = gl.getUniformLocation(lightingProgram,             'sunAngle');
  const uloc_lighting_sunAzimuth       = gl.getUniformLocation(lightingProgram,             'sunAzimuth');
  const uloc_lighting_sunColumnTex     = gl.getUniformLocation(lightingProgram,             'sunColumnTex');
  const uloc_realistic_sunAngle        = gl.getUniformLocation(realisticDisplayProgram,     'sunAngle');
  const uloc_realistic_sunAzimuth      = gl.getUniformLocation(realisticDisplayProgram,     'sunAzimuth');
  const uloc_realistic_sunColumnTex    = gl.getUniformLocation(realisticDisplayProgram,     'sunColumnTex');
  const uloc_realistic_minShadowLight  = gl.getUniformLocation(realisticDisplayProgram,     'minShadowLight');
  const uloc_sky_minShadowLight        = gl.getUniformLocation(skyBackgroundDisplayProgram, 'minShadowLight');
  const uloc_sky_sunAngle              = gl.getUniformLocation(skyBackgroundDisplayProgram, 'sunAngle');
  const uloc_sky_sunColumnTex          = gl.getUniformLocation(skyBackgroundDisplayProgram, 'sunColumnTex');
  const uloc_sky_timeOfDay             = gl.getUniformLocation(skyBackgroundDisplayProgram, 'timeOfDay');
  const uloc_sky_month                 = gl.getUniformLocation(skyBackgroundDisplayProgram, 'month');
  const uloc_setup_latitudeBasedTemperature = gl.getUniformLocation(setupProgram, 'latitudeBasedTemperature');
  const uloc_setup_multiLatitudeMode   = gl.getUniformLocation(setupProgram, 'multiLatitudeMode');
  const uloc_setup_latitude            = gl.getUniformLocation(setupProgram, 'latitude');
  const uloc_setup_latitudeLeft        = gl.getUniformLocation(setupProgram, 'latitudeLeft');
  const uloc_setup_latitudeRight       = gl.getUniformLocation(setupProgram, 'latitudeRight');
  const uloc_sky_starDensity           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'starDensity');
  const uloc_sky_starVisibility        = gl.getUniformLocation(skyBackgroundDisplayProgram, 'starVisibility');
  const uloc_sky_starLightEmitStrength = gl.getUniformLocation(skyBackgroundDisplayProgram, 'starLightEmitStrength');
  const uloc_sky_horizonLine           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHorizonLine');
  const uloc_sky_dayHue                = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDayHue');
  const uloc_sky_daySatLow             = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDaySatLow');
  const uloc_sky_daySatHigh            = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDaySatHigh');
  const uloc_sky_dayValLow             = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDayValLow');
  const uloc_sky_dayValHigh            = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDayValHigh');
  const uloc_sky_dayValPow             = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyDayValPow');
  const uloc_sky_twilightTop           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyTwilightTop');
  const uloc_sky_twilightUpper         = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyTwilightUpper');
  const uloc_sky_twilightMid           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyTwilightMid');
  const uloc_sky_twilightLow           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyTwilightLow');
  const uloc_sky_twilightHorizon       = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyTwilightHorizon');
  const uloc_sky_horizonDeepRed        = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHorizonDeepRed');
  const uloc_sky_horizonBurntOrange    = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHorizonBurntOrange');
  const uloc_sky_horizonGold           = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHorizonGold');
  const uloc_sky_horizonPaleGold       = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHorizonPaleGold');
  const uloc_sky_crepuscularColor      = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyCrepuscularColor');
  const uloc_sky_crepuscularStrength   = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyCrepuscularStrength');
  const uloc_sky_sunHorizAmplitude     = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skySunHorizAmplitude');
  const uloc_sky_sunVertScale          = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skySunVertScale');
  const uloc_sky_hazeMixStrength       = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHazeMixStrength');
  const uloc_sky_hazeBoostStrength     = gl.getUniformLocation(skyBackgroundDisplayProgram, 'skyHazeBoostStrength');

  // per-frame lighting
  const uloc_lighting_IR_rate          = gl.getUniformLocation(lightingProgram,             'IR_rate');

  // per-frame user input
  const uloc_adv_userInputValues       = gl.getUniformLocation(advectionProgram, 'userInputValues');
  const uloc_adv_userInputMove         = gl.getUniformLocation(advectionProgram, 'userInputMove');
  const uloc_adv_wrapHorizontally      = gl.getUniformLocation(advectionProgram, 'wrapHorizontally');
  const uloc_adv_userInputType         = gl.getUniformLocation(advectionProgram, 'userInputType');
  const uloc_adv_userInputCustomSlot   = gl.getUniformLocation(advectionProgram, 'userInputCustomSlot');
  const uloc_adv_userInputSurfaceKind  = gl.getUniformLocation(advectionProgram, 'userInputSurfaceKind');
  const uloc_adv_iterNum               = gl.getUniformLocation(advectionProgram, 'iterNum');
  const uloc_adv_brushOnlyMode         = gl.getUniformLocation(advectionProgram, 'brushOnlyMode');
  const uloc_vel_coriolisStrength      = gl.getUniformLocation(velocityProgram, 'coriolisStrength');

  // per-frame precipitation
  const uloc_precip_iterNum            = gl.getUniformLocation(precipitationProgram,     'iterNum');
  const uloc_precip_inactiveDroplets   = gl.getUniformLocation(precipitationProgram,     'inactiveDroplets');
  const uloc_precip_enableLegacyParticleLightning = gl.getUniformLocation(precipitationProgram, 'enableLegacyParticleLightning');
  const uloc_precip_lightningEnabled   = gl.getUniformLocation(precipitationProgram,     'lightningEnabled');
  const uloc_precip_lightningChanceMult = gl.getUniformLocation(precipitationProgram,    'lightningChanceMult');
  const uloc_precip_lightningCgWeight  = gl.getUniformLocation(precipitationProgram,     'lightningCgWeight');
  const uloc_precip_lightningSpiderWeight = gl.getUniformLocation(precipitationProgram,  'lightningSpiderWeight');
  const uloc_precip_lightningIcWeight  = gl.getUniformLocation(precipitationProgram,     'lightningIcWeight');
  const uloc_precip_lightningMinIters  = gl.getUniformLocation(precipitationProgram,     'lightningMinItersSinceLast');
  const uloc_precip_userInputValues    = gl.getUniformLocation(precipitationProgram,     'userInputValues');
  const uloc_precip_userInputType      = gl.getUniformLocation(precipitationProgram,     'userInputType');
  const uloc_precip_wrapHorizontally   = gl.getUniformLocation(precipitationProgram,     'wrapHorizontally');

  function uploadPrecipLightningSpawnUniforms()
  {
    if (uloc_precip_lightningEnabled)
      gl.uniform1i(uloc_precip_lightningEnabled, guiControls.enableLightning !== false ? 1 : 0);
    if (uloc_precip_lightningChanceMult)
      gl.uniform1f(uloc_precip_lightningChanceMult, getPrecipLightningChanceMult());
    if (uloc_precip_lightningMinIters)
      gl.uniform1f(uloc_precip_lightningMinIters, getPrecipLightningMinIters());
    if (uloc_precip_lightningCgWeight)
      gl.uniform1f(uloc_precip_lightningCgWeight, Math.max(guiControls.cloudToGroundFrequency || 0, 0));
    if (uloc_precip_lightningSpiderWeight)
      gl.uniform1f(uloc_precip_lightningSpiderWeight, Math.max(guiControls.spiderLightningFrequency || 0, 0));
    if (uloc_precip_lightningIcWeight)
      gl.uniform1f(uloc_precip_lightningIcWeight, Math.max(guiControls.intracloudFrequency || 0, 0));
  }
  const uloc_lightningLocation_iterNum = gl.getUniformLocation(lightningLocationProgram, 'iterNum');

  // bloom blur
  const uloc_bloom_bloomTexture        = gl.getUniformLocation(bloomBlurProgram, 'bloomTexture');
  const uloc_bloom_texelSize           = gl.getUniformLocation(bloomBlurProgram, 'texelSize');

  // passthrough
  const uloc_passthrough_texture       = gl.getUniformLocation(passthroughProgram, 'tex');

  // skyBackground per-frame
  const uloc_sky_aspectRatios          = gl.getUniformLocation(skyBackgroundDisplayProgram, 'aspectRatios');
  const uloc_sky_view                  = gl.getUniformLocation(skyBackgroundDisplayProgram, 'view');
  const uloc_sky_Xmult                 = gl.getUniformLocation(skyBackgroundDisplayProgram, 'Xmult');
  const uloc_sky_iterNum               = gl.getUniformLocation(skyBackgroundDisplayProgram, 'iterNum');
  const uloc_sky_visualQuality         = gl.getUniformLocation(skyBackgroundDisplayProgram, 'visualQuality');

  // realistic display per-frame
